import React from 'react'
import PropTypes from 'prop-types'
import {Text, VisuallyHidden} from '@salesforce/retail-react-app/app/components/shared/ui'
import {useIntl} from 'react-intl'
import msg from '@salesforce/retail-react-app/app/components/display-price/messages'

/**
 * Component that displays current price of a product with a11y
 * @param price - price of the product
 * @param as - an HTML tag or component to be rendered as
 * @param isRange - show price as range or not
 * @param currency - currency to show the price in
 * @param labelForA11y - label to be used for a11y
 * @param extraProps - extra props to be passed into Text Component
 * @returns {JSX.Element}
 */
const CurrentPrice = ({labelForA11y, price, as, isRange = false, currency, ...extraProps}) => {
    const intl = useIntl()
    const currentPriceText = intl.formatNumber(price, {
        style: 'currency',
        currency
    })
    return (
        <>
            {isRange ? (
                <Text
                    as={as}
                    {...extraProps}
                    aria-live={'polite'}
                    aria-label={intl.formatMessage(msg.ariaLabelCurrentPriceWithRange, {
                        currentPrice: currentPriceText
                    })}
                >
                    {intl.formatMessage(msg.currentPriceWithRange, {
                        currentPrice: currentPriceText
                    })}
                </Text>
            ) : (
                <Text
                    as={as}
                    {...extraProps}
                    aria-label={intl.formatMessage(msg.ariaLabelCurrentPrice, {
                        currentPrice: currentPriceText
                    })}
                >
                    {currentPriceText}
                </Text>
            )}
            {/*For screen reader, we want to make sure the product name is announced before the price to avoid confusion*/}
            <VisuallyHidden aria-live="polite" aria-atomic={true}>
                {labelForA11y}
                {isRange
                    ? intl.formatMessage(msg.ariaLabelCurrentPriceWithRange, {
                          currentPrice: currentPriceText
                      })
                    : intl.formatMessage(msg.ariaLabelCurrentPrice, {
                          currentPrice: currentPriceText
                      })}
            </VisuallyHidden>
        </>
    )
}
CurrentPrice.propTypes = {
    price: PropTypes.number.isRequired,
    currency: PropTypes.string.isRequired,
    labelForA11y: PropTypes.string,
    as: PropTypes.string,
    isRange: PropTypes.bool,
    extraProps: PropTypes.object
}

export default CurrentPrice

import { FONT_MEDIUM, FONT_REGULAR, FONT_SERIF } from './fonts';

// Typography scale primitives — deduplicated from the 22 Handover text styles below.
// zimmTokens.ts's --zimm-font-size-*/lineheight-*/letterspacing-* entries read from
// here too. Naming matches those --zimm-* suffixes.
export const fontSizes = {
  md: '1.5rem', // 24px
  xs: '1rem', // 16px
  '2xs': '0.875rem', // 14px
  '3xs': '0.75rem', // 12px
  '4xs': '0.625rem', // 10px
} as const;

export const lineHeights = {
  md: '2rem', // 32px
  xs: '1.5rem', // 24px
  '2xs': '1.125rem', // 18px
  '3xs': '1rem', // 16px
  '4xs': '0.875rem', // 14px
} as const;

export const letterSpacings = {
  sm: '0',
  xs: '-0.0075rem', // -0.12px
  // Only used by linkLg — still a named token rather than a raw literal so it can't
  // drift out of sync with globalStyles.ts's zimmTextLinkLg.
  '2xs': '-0.00875rem', // -0.14px
  footer: '0.025rem', // 0.4px
} as const;

export const fontWeights = {
  medium: '500',
  regular: '400',
} as const;

// Named text styles — source: Zimmermann Design System 2026 (Handover tokens/typography.css)
// Token name → fontFamily / fontWeight / fontSize / lineHeight / letterSpacing / transform
export const textStyles = {
  // ---- Headings ----
  // ZIM/h1-strong (.zimm-text-h1-strong): 500 weight, uppercase
  heading1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.md,
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/h1 (.zimm-text-h1): 400 weight, uppercase
  heading1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights.md,
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/h2-strong (.zimm-text-h2-strong)
  heading2: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.md,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.sm,
  },
  // ZIM/h3-strong (.zimm-text-h3-strong)
  heading3: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
    textTransform: 'uppercase' as const,
  },
  // ---- Body ----
  // ZIM/body1-strong (.zimm-text-body1-strong)
  body1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body1 (.zimm-text-body1)
  body1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body2-strong (.zimm-text-body2-strong)
  body2Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/body2 (.zimm-text-body2)
  body2: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Mobile body ----
  // ZIM/Mobile/Body1-strong (.zimm-text-mobile-body1-strong)
  mobileBody1Strong: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.xs,
  },
  // ZIM/Mobile/Body1 (.zimm-text-mobile-body1)
  mobileBody1: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ZIM/Mobile/Body2 (.zimm-text-mobile-body2)
  mobileBody2: {
    fontFamily: FONT_REGULAR,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.regular,
    lineHeight: lineHeights['4xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Utility ----
  // ZIM/Label (.zimm-text-label)
  label: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes.xs,
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights.xs,
    letterSpacing: letterSpacings.sm,
  },
  // Default/Caption (.zimm-text-caption)
  caption: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Links ----
  // ZIM/Link-lg (.zimm-text-link-lg): uppercase + underline
  linkLg: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings['2xs'],
    textTransform: 'uppercase' as const,
    textDecoration: 'underline',
  },
  // ZIM/Link-sm (.zimm-text-link-sm): uppercase + underline. Corrected from 'capitalize' to
  // 'uppercase' 2026-09-03 — confirmed against the live rendered text on Figma node
  // 40002163:41468 ("NOTIFY ME", fully capitalised), not the Handover token name alone.
  linkSm: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['4xs'],
    letterSpacing: letterSpacings.xs,
    textTransform: 'uppercase' as const,
    textDecoration: 'underline',
  },
  // ---- Buttons ----
  // ZIM/Button-lg — no .zimm-text-btn-lg class; zimmButton.css.ts composes this textStyle
  // directly (single source of truth for button styling).
  button: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/Button-sm — no .zimm-text-btn-sm class, same reason as the button style above.
  buttonSm: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ---- Commerce ----
  // ZIM/Product-name (.zimm-text-product-name)
  productNames: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ZIM/Price (.zimm-text-price)
  price: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['2xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['2xs'],
    letterSpacing: letterSpacings.sm,
  },
  // ---- Navigation ----
  // ZIM/Navigation (.zimm-text-nav)
  navigation: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.medium,
    lineHeight: 'normal',
    letterSpacing: letterSpacings.sm,
    textTransform: 'uppercase' as const,
  },
  // ---- Footer ----
  // ZIM/Footer (.zimm-text-footer)
  footer: {
    fontFamily: FONT_MEDIUM,
    fontSize: fontSizes['4xs'],
    fontWeight: fontWeights.medium,
    lineHeight: lineHeights['4xs'],
    letterSpacing: letterSpacings.footer,
    textTransform: 'uppercase' as const,
  },
  // ---- Serif accent (Source Serif 4, italic) ----
  // Default/Serif (.zimm-text-serif)
  serif: {
    fontFamily: FONT_SERIF,
    fontSize: fontSizes['3xs'],
    fontWeight: fontWeights.regular,
    fontStyle: 'italic' as const,
    lineHeight: lineHeights['3xs'],
    letterSpacing: letterSpacings.sm,
  },
};

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';

const ZIMM_INLINE_MESSAGE_RECIPE = 'ZimmInlineMessage';

export type ZimmInlineMessageProps = {
  /**
   * Colour/severity only — this atom never decides which one applies. A caller may legitimately
   * pass `variant="warning"` for copy whose own requirement text uses the word "error" (the cart
   * max-quantity message is exactly this case) — see zimmInlineMessage.css.ts's own docblock for
   * why that's a deliberate word-vs-severity reconciliation, not a mismatch to fix here.
   */
  variant: 'error' | 'warning';
  /**
   * Message copy, rendered verbatim. This atom never derives, hardcodes, or paraphrases copy — a
   * caller supplies the already-resolved string (e.g. "This item is unavailable", "Quantity
   * unavailable in this size", "Maximum purchase quantity reached for this size" — SFCC-795
   * §11.2 exact copy).
   */
  text: string;
};

/**
 * Atom — cart-line inline status message (SFCC-795 §11.2, plan step 3.2). Presentation only:
 * renders whatever `variant`/`text` it is given and never determines availability itself.
 * OOS/partial-OOS detection is SFCC-282's, "Unavailable" detection is SFCC-796's — both
 * later-sprint tickets this component does not, and should not, anticipate. No low-stock variant
 * exists in `ZimmInlineMessageProps['variant']` — a separate requirement explicitly forbids
 * low-stock messaging at the cart level (see zimmInlineMessage.css.ts).
 *
 * `aria-live="polite"` matches the same treatment this codebase already gives another transient,
 * non-input cart-line status value — ZimmQuantityStepper's own quantity display (its `value`
 * part, zimmQuantityStepper/index.tsx) carries the identical `aria-live="polite"` treatment — so
 * a shopper using assistive tech is told about a message that appears/changes after their own
 * action, without requiring focus to move to it.
 *
 * SFCC-795 rework (Marcel's own visual checkpoint against the real Figma file): the `warning`
 * variant renders a leading `info-solid` icon, `error` never does — confirmed against 3 real
 * cart-item instances in Figma file QQ427wHWEUjsjP7H8v48Rs: the two error-copy states (FULLY OOS
 * node 9323-101979, PARTIAL OOS node 9323-98397) have no icon in their message sub-tree; the
 * warning-copy state's own "Cart Item" instance (9323:106685 — one of 5 per-item rows inside the
 * "WARNINGS SHOWN" frame's "Cart-item-group", not that frame's separate SFCC-404
 * "Cart-level-messages" sibling — see zimmInlineMessage.css.ts for the full parent-chain
 * citation) does. The icon is `aria-hidden` — the
 * message's own text plus `aria-live` already carry the full meaning to assistive tech, so the
 * icon is a purely visual (sighted-only) reinforcement of a severity already conveyed by colour
 * and copy, not an independent piece of information.
 *
 * @param props see ZimmInlineMessageProps
 */
export const ZimmInlineMessage = ({ variant, text }: ZimmInlineMessageProps) => {
  const styles = useMultiStyleConfig(ZIMM_INLINE_MESSAGE_RECIPE, { variant });

  return (
    <chakra.div __css={styles.root} aria-live="polite" data-testid="zimm-inline-message">
      {variant === 'warning' && <ZimmIcon type="info-solid" size="md" aria-hidden />}
      <chakra.p __css={styles.text}>{text}</chakra.p>
    </chakra.div>
  );
};

/**
 * Recipe — cart-line inline status message (SFCC-795 §11.2, plan step 3.2).
 * `.claude/session-notes.md` §11.2: "inline message (error/warning) sits between the stepper and
 * the actions, w-full, `Default/Caption` regular 12px / lh18. In error states the Item Details
 * gap widens 12 -> 16px." (the gap widening is `ZimmCartItem`'s own `hasError` resolution prop —
 * see product-item.css.ts — not this recipe's concern; this file owns only the message's own
 * type/colour/icon.)
 *
 * Two-part multipart recipe (`root`/`text`), following zimmDrawer.css.ts's plain-object
 * `{parts, baseStyle, variants}` shape rather than `defineStyleConfig` — no Chakra helper
 * factory, same Chakra-native string `variants` resolution either form supports.
 *
 * Restructured from a single-node `defineStyleConfig` (SFCC-795 rework — Marcel's own visual
 * checkpoint against the real Figma file surfaced a genuine gap the original single-node shape
 * couldn't express): the `warning` variant carries a leading 16x16 icon, the `error` variant
 * never does. This was already a known requirement, not something discovered fresh at the
 * checkpoint or borrowed from an unrelated ticket — `.claude/session-notes.md:395` (the original
 * SFCC-795 ticket restatement, written before any Figma metadata was pulled) already says
 * "warning state (grey info icon + message, e.g. 'Maximum purchase quantity reached for this
 * size')", the exact copy string used here. It was simply dropped somewhere between that
 * restatement and the written build plan's step 3.2 text, and the checkpoint is what caught it.
 *
 * Confirmed against 3 real cart-item instances in Figma file QQ427wHWEUjsjP7H8v48Rs
 * ("Zimmermann_Designs") — the two error-copy states (FULLY OOS node 9323-101979, PARTIAL OOS
 * node 9323-98397) have a bare `<text>` message sub-tree, no icon; the warning-copy state's own
 * "Cart Item" instance is `icon(16x16, x=0) -> 8px gap -> text(x=24)`. That instance is node
 * 9323:106685, named "Cart Item" — confirmed via its own metadata to be one of 5 per-item rows
 * inside the "Cart-item-group" frame, i.e. genuinely SFCC-270/795's own per-item scope. It is
 * NOT the same as "Cart-level-messages" (a distinct sibling instance, 1186x52, that the same
 * top-level "WARNINGS SHOWN" frame (9323-90299) also contains at the page level) — that one is
 * SFCC-404's cart-level banner, a wholly different component this build does not touch. The two
 * share a parent frame and a similar 8px gap value, which is what makes them easy to conflate at
 * a glance; the "Cart Item"/"Cart-level-messages" instance names are what actually disambiguate
 * them, confirmed directly rather than inferred from proximity.
 *
 * So the single implicit node this recipe used to describe is no longer enough: `root` is now
 * the flex row wrapping the optional icon + the text, and `text` carries what used to be the
 * whole recipe's `baseStyle`.
 *
 * No separate `icon` part: `ZimmIcon`'s own `color` prop defaults to `currentColor`
 * (zimmIcon/index.tsx), and Chakra's `Icon` component passes `color` straight through as the
 * rendered SVG's own inline CSS `color` rather than resolving it to a token itself (confirmed
 * directly in `@chakra-ui/icon`'s `Icon` implementation) — so the icon element's own
 * `stroke="currentColor"` shapes (zimm.tsx's `InfoSolidIcon`) inherit `root`'s `color` via
 * ordinary CSS inheritance for free. Nothing to declare on this recipe's side for the icon.
 *
 * --- Typography: regular weight is a DELIBERATE override, on a DIFFERENT Figma node than the
 * one commit 5 (SFCC-270) corrected — read both before touching either ---
 * `textStyle: 'caption'` supplies the correct 12px size / 18px line-height pair, but this
 * codebase's `caption` textStyle (theme/foundation/typography.ts) is MEDIUM-weight
 * (`fontWeight: fontWeights.medium`) — that is exactly right for Figma's OTHER caption node,
 * `Default/Caption-strong` (the cart-item colour+size line — see
 * item-variant/item-variant.css.ts:73-84, which deliberately keeps `caption` with NO fontWeight
 * override for that reason, having removed an earlier, backwards override). THIS element is
 * Figma's plain, un-strong `Default/Caption` node, which is REGULAR-weight per the session-notes
 * citation above — the opposite correction, on a different string, elsewhere in the same design
 * file. `fontWeight` is therefore set explicitly below, on the `text` part, to override the
 * textStyle-expanded medium value back down to regular — the same "a direct CSS prop applied
 * after the textStyle expansion wins in Chakra's style pipeline" mechanism zimmButton.css.ts's
 * `sizes.lg`/`sizes.sm` already documents and relies on for the identical reason.
 *
 * `root.width: 'full'` reproduces Figma's own "w-full" annotation for this element explicitly,
 * rather than relying on this node's flex/stack parent to stretch it by default — moved here
 * from the (no-longer-existing) single node, since `root` is now the outer container.
 *
 * `root.alignItems: 'flex-start'`: top-aligned, not centred — the warning icon sits at the top
 * of what can be 2-line-wrapped text, not vertically centred against it. Confirmed via the
 * Figma metadata's own y-positions on the "Cart Item" instance cited above (9323:106685): the
 * icon instance sits at y=0 within its frame, the same top edge the text frame starts from.
 *
 * `root.gap: 'var(--zimm-scale-xs)'` (8px): that same "Cart Item" instance places the 16px-wide icon at
 * x=0 and the text frame starting at x=24 — the 8px difference between them is the gap.
 *
 * No low-stock variant: a separate requirement explicitly forbids low-stock messaging at the
 * cart level (SFCC-795 §11.2 build decisions) — the variants map below only ever has the two
 * keys `error`/`warning`; do not add a third.
 */
const baseStyle = {
  root: {
    display: 'flex',
    alignItems: 'flex-start',
    gap: 'var(--zimm-scale-xs)',
    width: 'full',
  },
  text: {
    textStyle: 'caption',
    fontWeight: 'var(--zimm-font-weight-regular)',
    // Standard flexbox text-truncation-prevention: without these, a long message next to the
    // fixed-size icon in this flex row can be squeezed narrower than its own content instead of
    // wrapping onto its own available width. `flex: 1` lets the text claim the row's remaining
    // space (the icon, an intrinsically-sized SVG, takes only what it needs); `minWidth: 0`
    // overrides a flex item's own default `min-width: auto`, which would otherwise refuse to
    // shrink the text below its content's intrinsic width and push `root` wider than its own
    // `width: full`.
    flex: 1,
    minWidth: 0,
  },
};

const variants = {
  // Figma `text/error` #9c0000 -> status.error (session-notes.md §11.10(6) colour audit).
  error: {
    root: {
      color: 'var(--zimm-color-status-error)',
    },
  },
  // Figma `text/muted` / `text/subtlest` #969696 -> both collapse onto this one token, no
  // ambiguity in this codebase's own set (session-notes.md §11.10(6)). This is also the same
  // token the InfoSolidIcon's own real Figma export colour (#969696) coincidentally matches —
  // see that icon's own citation in zimm.tsx — not a second, independent confirmation of the
  // token choice, just a coincidence worth noting there and here.
  //
  // Max-quantity messaging ("Maximum purchase quantity reached for this size") uses THIS variant,
  // not `error` — even though its own requirement/AC text uses the word "error" to describe it.
  // That word is describing "user-facing feedback" in the requirement's own vocabulary, not
  // asserting the error SEVERITY tier: the actual Figma design and that story's own AC agree the
  // rendered treatment is grey/warning, not red/error. Deliberate word-vs-severity reconciliation,
  // settled at this build's planning gate — not a mistake, and not to be "corrected" back to
  // `error` by a future reader matching the word alone.
  warning: {
    root: {
      color: 'var(--zimm-color-text-muted)',
    },
  },
};

export const ZimmInlineMessage = {
  parts: ['root', 'text'],
  baseStyle,
  variants,
};

import { breakpoints } from 'app/theme/foundation';

// Figma "Image" spec (product-item card, SFCC-270): 132x198 desktop, 67x100 mobile — no
// --zimm-scale equivalent exists at either pixel pair.
// audit-allow: Figma-confirmed cart-item image dimensions, no foundation token at this value.
const IMAGE_WIDTH_MOBILE = '67px';
const IMAGE_WIDTH_DESKTOP = '132px';

// Figma "colour + size" caption string: 200px, no --zimm-scale equivalent at this value.
// audit-allow: Figma-confirmed width, no foundation token at this value.
const COLOUR_SIZE_WIDTH = '200px';

/**
 * Recipe key — single source of truth, imported by item-image.tsx/item-attributes.tsx/
 * item-price.tsx instead of each redeclaring the same string literal (SFCC-270 round 2 rework).
 */
export const ZIMM_CART_ITEM_VARIANT_RECIPE = 'ZimmCartItemVariant';

/**
 * Co-located recipe for the item-variant family (item-image / item-attributes / item-price).
 * SFCC-270 (plan step 2.2).
 *
 * Parts:
 *   - `image` — item-image.tsx's outer Box: responsive width, ivory-200 background. Applied
 *     via `__css`, not `sx` — this one MUST stay overridable: order-summary/index.jsx (base
 *     SFCC, not yet overridden in this repo) calls
 *     `<CartItemVariantImage width="80px" mr={2} />` and depends on its own caller-supplied
 *     `width` winning over whatever default this component ships. `__css` is the lowest-
 *     priority slot in `@chakra-ui/system`'s `toCSSObject` merge (`chunk-E32MZNBA.mjs`:
 *     `assignAfter({}, __css, baseStyle, styleProps, sx)`), and `Box` carries no competing
 *     baseStyle of its own (`@chakra-ui/layout`'s `chunk-6CSUKJP7.mjs`: `var Box =
 *     chakra("div")`, no options) — confirmed by reading both files, not assumed — so a
 *     literal caller prop always wins over this part's `__css` default.
 *   - `img` — the inner <Image>: responsive objectFit (contain mobile / cover desktop) plus
 *     mix-blend-multiply, so the photo blends against the `image` part's ivory backdrop.
 *     `__css` is safe here too — Chakra's own `Image` (`@chakra-ui/image`'s
 *     `chunk-SMHKDLMK.mjs`) never sets a literal `__css` key of its own, unlike `Text` below.
 *   - `colourSize` — item-attributes.tsx's combined "colour, size" string.
 *   - `price` — item-price.tsx's price Stack (`textStyle: 'price'` only; the actual price
 *     digits render via the base, un-overridden `display-price`/`current-price` components,
 *     which set no competing font-size of their own — confirmed by reading both files — so
 *     the textStyle cascades down via ordinary CSS inheritance without touching either file).
 *
 * `colourSize` and `price` are applied via `sx`, not `__css`: Chakra's own `Text`
 * (`@chakra-ui/layout`'s `chunk-P74GIWPW.mjs`) places its OWN `__css={styles}` (from
 * `useStyleConfig('Text', props)`) as a literal key AFTER `...rest` in its own render call —
 * a caller-supplied `__css` prop would be silently discarded entirely there (a later
 * same-named key in one object literal replaces the earlier one; it does not merge). `sx` is
 * destructured separately by `toCSSObject` and isn't subject to that collision, so it's the
 * reliable way to style a plain `<Text>`/`<Stack>` from outside. Verified by reading the
 * compiled source directly. `price`'s own Stack has no such hazard (`@chakra-ui/layout`'s
 * `chunk-WKZT7ZXJ.mjs` Stack sets no literal `__css` key at all), so either mechanism would
 * have worked there — `sx` is used anyway, for one consistent rule across this file's parts
 * rather than a different mechanism per element.
 */
export const ZimmCartItemVariant = {
  parts: ['image', 'img', 'colourSize', 'price'],
  baseStyle: {
    image: {
      width: IMAGE_WIDTH_MOBILE,
      backgroundColor: 'var(--zimm-color-bg-02)',
      [`@media (min-width: ${breakpoints.md})`]: {
        width: IMAGE_WIDTH_DESKTOP,
      },
    },
    img: {
      objectFit: 'contain',
      mixBlendMode: 'multiply',
      [`@media (min-width: ${breakpoints.md})`]: {
        objectFit: 'cover',
      },
    },
    colourSize: {
      textStyle: 'caption',
      // No fontWeight override here (round 2 rework — corrects the prior round's backwards
      // reasoning). Figma's colour+size string is the MEDIUM-weight "Default/Caption-strong"
      // node, not the regular-weight "Default/Caption" node — .claude/session-notes.md says so
      // twice, independently, both dated 2026-09-16 and headed RESOLVED: §11.2 ("colour + size:
      // ONE combined string ... `Default/Caption-strong` 12px / lh18") and §11.10(5) ("no
      // `captionStrong` for Figma's `Default/Caption-strong` (the cart item's colour+size line,
      // medium/500) — we only have `caption`"). This repo's `caption` textStyle
      // (theme/foundation/typography.ts) is already medium-weight (`fontWeight:
      // fontWeights.medium`), i.e. it already matches Default/Caption-strong, so `textStyle:
      // 'caption'` alone gives the correct weight with nothing to override.
      width: COLOUR_SIZE_WIDTH,
      color: 'var(--zimm-color-text-secondary)',
    },
    price: {
      textStyle: 'price',
    },
  },
};

