content.content:
1	/**
2	 * SFCC-270 (plan step 2.2). Covers:
3	 *   - item-image.tsx: a caller-supplied `width`/`mr` must win over the Zimmermann default
4	 *     (item-variant.css.ts's `image` part) — this is exactly what order-summary/index.jsx's
5	 *     (base, not-yet-overridden) `<CartItemVariantImage width="80px" mr={2} />` depends on.
6	 *   - item-name.tsx: a caller-supplied `color` must win over the Zimmermann default — the bug
7	 *     fix at this step (base had the spread BEFORE the explicit `color`, silently discarding
8	 *     any caller value).
9	 *   - item-attributes.tsx (round 2 rework): the pre-existing per-key rendering path — used
10	 *     unmodified today by order-summary, wishlist/checkout partials, account/order-detail, and
11	 *     the confirmation page — still renders correctly now that it sits behind this build's new
12	 *     `!combineAttributeValues &&` guard.
13	 *   - item-price.tsx (round 2 rework, should-fix): the `isDesktop`-gated PricePerItem
14	 *     positioning, the `isOnSale`-driven stack spacing, and the `price` recipe's textStyle.
15	 *
16	 * `useMultiSite` is mocked, not provided via a real MultiSiteProvider: item-name.tsx's <Link>
17	 * calls it internally, and its real dependency chain (`@salesforce/retail-react-app/app/
18	 * contexts`) fails to parse under Vitest's Vite transform — same mock, same reasoning, as
19	 * header/rightBar/index.test.tsx's own `vi.mock('.../use-multi-site', ...)`.
20	 *
21	 * item-attributes.tsx/item-price.tsx pull in several more hooks that need the same treatment,
22	 * all following that identical established pattern (mock the smallest surface, per
23	 * .claude/rules/testing.md): `useCurrency` (full replacement — this file's render tree never
24	 * needs the real `useDerivedProduct` also exported from that barrel, unlike
25	 * product-item/index.test.tsx, so no `vi.importActual` juggling is needed here), a real-network
26	 * `useCurrentBasket`, `PromoPopover` (imports the base icons barrel, throws under Vitest per
27	 * testing.md's documented ZimmIcon gap), and `usePromotions`/`useProducts`/`useProduct` from
28	 * `@salesforce/commerce-sdk-react`. `useBreakpointValue` is mocked directly (from `@chakra-ui/react`,
29	 * which `shared/ui`'s own `useBreakpointValue` module just re-exports) so item-price.tsx's
30	 * `isDesktop` resolves to an exact, per-test value — the same pattern
31	 * zimmSizeSelector/index.test.tsx already establishes, rather than fighting Chakra's internal
32	 * breakpoint-matching media queries via a `window.matchMedia` mock.
33	 *
34	 * SFCC-795 (plan step 3.3) adds one more mock, `getPriceData` from `product-utils` (smallest
35	 * surface, `...actual` spread keeps `getDisplayVariationValues` real for the attributes tests
36	 * above, which depend on it) — see the new "promotional price (was/now)" describe block below for
37	 * why: `getPriceData` requires a real product/variant shape (master/set detection, tieredPrices)
38	 * this file has no reason to construct correctly, and this suite is about item-price.tsx's own
39	 * forwarding/scaling contract, not about re-proving `getPriceData`'s own correctness (same
40	 * reasoning this file already applies to `getDisplayVariationValues` two paragraphs up).
41	 */
42	import React from 'react';
43	import { describe, test, expect, vi, beforeEach } from 'vitest';
44	import { render, screen } from '@testing-library/react';
45	import { ChakraProvider, useBreakpointValue } from '@chakra-ui/react';
46	import { IntlProvider } from 'react-intl';
47	import { MemoryRouter } from 'react-router-dom';
48	import theme from 'app/theme';
49	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
50	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
51	import ItemVariantProvider from '.';
52	import CartItemVariantImage from './item-image';
53	import CartItemVariantName from './item-name';
54	import CartItemVariantAttributes from './item-attributes';
55	import CartItemVariantPrice from './item-price';
56	
57	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
58	  default: vi.fn(),
59	}));
60	
61	// SFCC-795 (plan step 3.3): smallest-surface override, real `getDisplayVariationValues` kept via
62	// `...actual` — see this file's own top-of-file docblock addition for why.
63	vi.mock('@salesforce/retail-react-app/app/utils/product-utils', async (importOriginal) => {
64	  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/utils/product-utils')>();
65	  return {
66	    ...actual,
67	    getPriceData: vi.fn(),
68	  };
69	});
70	
71	vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
72	  useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
73	}));
