/**
 * SFCC-270 (plan step 2.2). Covers:
 *   - item-image.tsx: a caller-supplied `width`/`mr` must win over the Zimmermann default
 *     (item-variant.css.ts's `image` part) — this is exactly what order-summary/index.jsx's
 *     (base, not-yet-overridden) `<CartItemVariantImage width="80px" mr={2} />` depends on.
 *   - item-name.tsx: a caller-supplied `color` must win over the Zimmermann default — the bug
 *     fix at this step (base had the spread BEFORE the explicit `color`, silently discarding
 *     any caller value).
 *   - item-attributes.tsx (round 2 rework): the pre-existing per-key rendering path — used
 *     unmodified today by order-summary, wishlist/checkout partials, account/order-detail, and
 *     the confirmation page — still renders correctly now that it sits behind this build's new
 *     `!combineAttributeValues &&` guard.
 *   - item-price.tsx (round 2 rework, should-fix): the `isDesktop`-gated PricePerItem
 *     positioning, the `isOnSale`-driven stack spacing, and the `price` recipe's textStyle.
 *
 * `useMultiSite` is mocked, not provided via a real MultiSiteProvider: item-name.tsx's <Link>
 * calls it internally, and its real dependency chain (`@salesforce/retail-react-app/app/
 * contexts`) fails to parse under Vitest's Vite transform — same mock, same reasoning, as
 * header/rightBar/index.test.tsx's own `vi.mock('.../use-multi-site', ...)`.
 *
 * item-attributes.tsx/item-price.tsx pull in several more hooks that need the same treatment,
 * all following that identical established pattern (mock the smallest surface, per
 * .claude/rules/testing.md): `useCurrency` (full replacement — this file's render tree never
 * needs the real `useDerivedProduct` also exported from that barrel, unlike
 * product-item/index.test.tsx, so no `vi.importActual` juggling is needed here), a real-network
 * `useCurrentBasket`, `PromoPopover` (imports the base icons barrel, throws under Vitest per
 * testing.md's documented ZimmIcon gap), and `usePromotions`/`useProducts`/`useProduct` from
 * `@salesforce/commerce-sdk-react`. `useBreakpointValue` is mocked directly (from `@chakra-ui/react`,
 * which `shared/ui`'s own `useBreakpointValue` module just re-exports) so item-price.tsx's
 * `isDesktop` resolves to an exact, per-test value — the same pattern
 * zimmSizeSelector/index.test.tsx already establishes, rather than fighting Chakra's internal
 * breakpoint-matching media queries via a `window.matchMedia` mock.
 *
 * SFCC-795 (plan step 3.3) adds one more mock, `getPriceData` from `product-utils` (smallest
 * surface, `...actual` spread keeps `getDisplayVariationValues` real for the attributes tests
 * above, which depend on it) — see the new "promotional price (was/now)" describe block below for
 * why: `getPriceData` requires a real product/variant shape (master/set detection, tieredPrices)
 * this file has no reason to construct correctly, and this suite is about item-price.tsx's own
 * forwarding/scaling contract, not about re-proving `getPriceData`'s own correctness (same
 * reasoning this file already applies to `getDisplayVariationValues` two paragraphs up).
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider, useBreakpointValue } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import theme from 'app/theme';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
import ItemVariantProvider from '.';
import CartItemVariantImage from './item-image';
import CartItemVariantName from './item-name';
import CartItemVariantAttributes from './item-attributes';
import CartItemVariantPrice from './item-price';

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

// SFCC-795 (plan step 3.3): smallest-surface override, real `getDisplayVariationValues` kept via
// `...actual` — see this file's own top-of-file docblock addition for why.
vi.mock('@salesforce/retail-react-app/app/utils/product-utils', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/utils/product-utils')>();
  return {
    ...actual,
    getPriceData: vi.fn(),
  };
});

vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
  useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
  useCurrentBasket: () => ({ data: undefined }),
}));

vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
}));

vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
  return {
    ...actual,
    usePromotions: () => ({ data: undefined }),
    useProducts: () => ({ data: undefined, isLoading: false }),
    useProduct: () => ({ data: undefined, isLoading: false }),
  };
});

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useBreakpointValue: vi.fn(),
  };
});

const mockUseMultiSite = vi.mocked(useMultiSite);
const mockUseBreakpointValue = vi.mocked(useBreakpointValue);
const mockGetPriceData = vi.mocked(getPriceData);

// ChakraProvider with this project's own theme is required, not optional here — without it,
// `textStyle="productNames"` resolves against Chakra's default (empty) textStyles, and
// `useBreakpointValue` (item-price.tsx, exercised transitively were this file to render it)
// throws outright reading `theme.breakpoints` off an undefined theme. Same setup zimmButton's
// own test uses.
const renderWithProviders = (ui: React.ReactElement) =>
  render(
    <ChakraProvider theme={theme}>
      <MemoryRouter>
        <IntlProvider locale="en-AU" defaultLocale="en-AU">
          {ui}
        </IntlProvider>
      </MemoryRouter>
    </ChakraProvider>,
  );

const baseVariant = {
  id: 'variant-1',
  productName: 'Lilac Sand Dress',
  imageGroups: [
    {
      viewType: 'small',
      images: [{ alt: 'Lilac Sand Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
    },
  ],
};

describe('item-variant', () => {
  beforeEach(() => {
    mockUseMultiSite.mockReturnValue({
      site: { id: 'ZimmermannAU' },
      buildUrl: (path: string) => path,
    });
  });

  describe('CartItemVariantImage (item-image) — defaults-then-spread', () => {
    test('a caller-supplied width wins over the Zimmermann default', () => {
      const { container } = renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantImage width="321px" />
        </ItemVariantProvider>,
      );
      const box = container.firstElementChild as HTMLElement;
      expect(box).toHaveStyle({ width: '321px' });
    });

    test('a caller-supplied mr is applied (the exact regression that would break order-summary)', () => {
      const { container } = renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantImage mr="37px" />
        </ItemVariantProvider>,
      );
      const box = container.firstElementChild as HTMLElement;
      expect(box).toHaveStyle({ marginRight: '37px' });
    });
  });

  describe('CartItemVariantName (item-name) — spread-order bug fix', () => {
    test('a caller-supplied color wins over the Zimmermann default', () => {
      renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantName color="rgb(255, 0, 0)" />
        </ItemVariantProvider>,
      );
      const link = screen.getByRole('link', { name: 'Lilac Sand Dress' });
      expect(link).toHaveStyle({ color: 'rgb(255, 0, 0)' });
    });

    test('renders uppercase via textStyle="productNames" (text-transform, not literal casing)', () => {
      renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantName />
        </ItemVariantProvider>,
      );
      // Asserted on the <Heading> textStyle is actually applied to, not the nested <Link> —
      // text-transform is CSS-inherited from parent to child, and jsdom's getComputedStyle does
      // not reliably resolve inherited (as opposed to directly-applied) declarations.
      const heading = screen.getByRole('heading', { level: 2 });
      expect(heading).toHaveStyle({ textTransform: 'uppercase' });
    });
  });

  describe('CartItemVariantAttributes (item-attributes) — combineAttributeValues default (per-key) path', () => {
    // Shape matches getDisplayVariationValues's own real contract (product-utils.js) — the real,
    // unmocked utility is exercised here, not stubbed, since this test is specifically about the
    // per-key rendering path's own contract.
    const attributesVariant = {
      id: 'variant-1',
      productName: 'Lilac Sand Dress',
      variationAttributes: [
        { id: 'color', name: 'Colour', values: [{ value: 'JJ5FUXX', name: 'Lilac Sand', orderable: true }] },
        { id: 'size', name: 'Size', values: [{ value: 'ONESIZE', name: 'One Size', orderable: true }] },
      ],
      variationValues: { color: 'JJ5FUXX', size: 'ONESIZE' },
    };

    // Round 2 rework (must-fix 2): this branch has six real, unmodified callers today
    // (order-summary, wishlist partials, checkout partials, account/order-detail, the
    // confirmation page) and none of them pass combineAttributeValues — this proves this
    // build's new `!combineAttributeValues &&` guard still renders their per-key output.
    test('renders one Text per variation-value key, with labels, when combineAttributeValues is omitted', () => {
      renderWithProviders(
        <ItemVariantProvider variant={attributesVariant}>
          <CartItemVariantAttributes />
        </ItemVariantProvider>,
      );

      expect(screen.getByText('Colour: Lilac Sand')).toBeInTheDocument();
      expect(screen.getByText('Size: One Size')).toBeInTheDocument();
      // Not the combined-string shape — proves the per-key branch rendered, not the combined one.
      expect(screen.queryByText('Lilac Sand, One Size')).not.toBeInTheDocument();
    });

    test('hideAttributeLabels still renders per-key (one Text per key), just without the "Key: " prefix', () => {
      renderWithProviders(
        <ItemVariantProvider variant={attributesVariant}>
          <CartItemVariantAttributes hideAttributeLabels />
        </ItemVariantProvider>,
      );

      expect(screen.getByText('Lilac Sand')).toBeInTheDocument();
      expect(screen.getByText('One Size')).toBeInTheDocument();
      expect(screen.queryByText('Colour: Lilac Sand')).not.toBeInTheDocument();
    });
  });

  describe('CartItemVariantPrice (item-price) — rendering logic', () => {
    const priceVariant = (overrides: Record<string, unknown> = {}) => ({
      id: 'variant-1',
      itemId: 'item-1',
      name: 'Lilac Sand Dress',
      price: 200,
      priceAfterItemDiscount: 200,
      pricePerUnit: 100,
      quantity: 2,
      ...overrides,
    });

    test('isDesktop-gated positioning: PricePerItem renders before the main price on mobile, after it on desktop', () => {
      mockUseBreakpointValue.mockReturnValue(false);
      const mobile = renderWithProviders(
        <ItemVariantProvider variant={priceVariant()}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      const perItemMobile = screen.getByText('$100.00ea');
      const mainPriceMobile = screen.getByText('$200.00');
      // Node.DOCUMENT_POSITION_FOLLOWING: mainPrice comes AFTER perItem in document order.
      expect(perItemMobile.compareDocumentPosition(mainPriceMobile) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
      mobile.unmount();

      mockUseBreakpointValue.mockReturnValue(true);
      renderWithProviders(
        <ItemVariantProvider variant={priceVariant()}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      const perItemDesktop = screen.getByText('$100.00ea');
      const mainPriceDesktop = screen.getByText('$200.00');
      // Reversed: perItem now comes AFTER mainPrice.
      expect(
        mainPriceDesktop.compareDocumentPosition(perItemDesktop) & Node.DOCUMENT_POSITION_FOLLOWING,
      ).toBeTruthy();
    });

    test('isOnSale collapses the price Stack spacing to 0, otherwise theme.space[1] (0.25rem)', () => {
      mockUseBreakpointValue.mockReturnValue(false);

      const notOnSale = renderWithProviders(
        <ItemVariantProvider variant={priceVariant({ price: 200, priceAfterItemDiscount: 200, quantity: 1 })}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      const notOnSaleStack = notOnSale.container.firstElementChild as HTMLElement;
      // Chakra/emotion emits a CSS custom-property reference for a registered space-scale
      // value, not the literal rem — confirmed by reading the actual rendered style, not assumed.
      expect(notOnSaleStack).toHaveStyle({ gap: 'var(--chakra-space-1)' });
      notOnSale.unmount();

      const onSale = renderWithProviders(
        <ItemVariantProvider variant={priceVariant({ price: 250, priceAfterItemDiscount: 200, quantity: 1 })}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      const onSaleStack = onSale.container.firstElementChild as HTMLElement;
      // Unlike space[1] above, Chakra's own default scale has no `0` key at all (confirmed by
      // reading @chakra-ui/theme's spacing chunk) — so `spacing={0}` isn't a scale lookup, it's
      // the literal value passed straight through, rendering as a plain `0px`, not a CSS var.
      expect(onSaleStack).toHaveStyle({ gap: '0px' });
    });

    test('applies the price recipe (textStyle) directly to its own Stack', () => {
      mockUseBreakpointValue.mockReturnValue(false);
      const { container } = renderWithProviders(
        <ItemVariantProvider variant={priceVariant({ quantity: 1 })}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      const stack = container.firstElementChild as HTMLElement;
      // theme/foundation/typography.ts's `price` textStyle: fontSize '2xs' (0.875rem), fontWeight
      // medium (500) — verified against the real registered scale, not assumed.
      expect(stack).toHaveStyle({ fontSize: '0.875rem', fontWeight: '500' });
    });
  });

  /**
   * SFCC-795 (plan step 3.3), pass criterion 1: "With isOnSale and a listPrice, the struck 'Was'
   * and the 'Now' both render, and both scale with quantity." Base `display-price` (see that
   * component's own `index.jsx`) is the mechanism: `quantity` defaults to 1 and both
   * `currentPrice * quantity` (CurrentPrice/"Now") and `listPrice * quantity` (ListPrice/"Was",
   * only when `listPrice` is truthy) are multiplied by whatever `quantity` this file's own
   * `<DisplayPrice quantity={variant?.quantity} .../>` call passes through.
   *
   * DISCLOSED LIMITATION, verified directly against the real (unmodified, copy-first-ported)
   * base file rather than assumed: this file's OTHER branch — `variant?.itemId` truthy, i.e. a
   * real basket-sourced cart line item — hardcodes `listPrice: null` ("we don't want to show
   * strikethrough price for cart since listPrice is not available via basket pricing", this
   * file's own inline comment, byte-identical to
   * node_modules/@salesforce/retail-react-app/app/components/item-variant/item-price.jsx, diffed
   * directly) and passes NO `quantity` prop to `DisplayPrice` at all. So a REAL cart/basket line
   * item cannot reach this mechanism today, regardless of Zimmermann styling — this is inherited,
   * unmodified base SFCC behaviour (confirmed unchanged since the SFCC-270 copy-first port, plan
   * step 2.1), not something this step's own "Changes" scope (the discountLabel prop, ProductItem
   * only) touches or was asked to fix.
   *
   * This describe block therefore proves the mechanism via item-price.tsx's OTHER, non-basket
   * branch (`variant?.itemId` falsy, `getPriceData(variant)` — the same branch this file's own
   * docblock already documents as "for wishlist page", i.e. a real, already-existing caller shape
   * of this exact shared component, not a fictional one) — `getPriceData` itself is mocked (see
   * top-of-file) so this test controls `isOnSale`/`listPrice`/`currentPrice` directly rather than
   * needing a fully realistic master/set/tieredPrices product shape.
   *
   * Flagged in this build's report for Marcel: pass criterion 1 is proven true of the mechanism,
   * not proven reachable via any real Zimmermann cart line item as this file stands today.
   */
  describe('CartItemVariantPrice (item-price) — promotional price / was-now (SFCC-795, plan step 3.3)', () => {
    test('isOnSale + listPrice: the struck Was and the current Now both render, and both scale with quantity', () => {
      mockUseBreakpointValue.mockReturnValue(false);
      mockGetPriceData.mockReturnValue({
        currentPrice: 160,
        listPrice: 200,
        isOnSale: true,
        isASet: false,
        isMaster: false,
        isRange: false,
      });

      const atQuantityTwo = renderWithProviders(
        <ItemVariantProvider variant={{ id: 'variant-1', name: 'Lilac Sand Dress', quantity: 2 }}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      // Now: currentPrice (160) * quantity (2).
      expect(screen.getByText('$320.00')).toBeInTheDocument();
      // Was: listPrice (200) * quantity (2), struck (base ListPrice renders as <Text as="s">).
      expect(screen.getByText('$400.00')).toBeInTheDocument();
      atQuantityTwo.unmount();

      // Re-render at quantity 1 to positively prove "scale with quantity", not just correctness
      // at one fixed value.
      const atQuantityOne = renderWithProviders(
        <ItemVariantProvider variant={{ id: 'variant-1', name: 'Lilac Sand Dress', quantity: 1 }}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      expect(screen.getByText('$160.00')).toBeInTheDocument();
      expect(screen.getByText('$200.00')).toBeInTheDocument();
      atQuantityOne.unmount();
    });
  });
});

/**
 * SFCC-270 round 2 rework, extended post-rework (found live in Storybook by Marcel, not by this
 * suite). Proves three stacked bugs are actually fixed TOGETHER, not just that the symbols were
 * added:
 *   1. `useVariationAttributes` -> `isVariantValueOrderable` (base SFCC hook, unconditional
 *      `product.variants.filter(...)`) needs `variants` to be an array on the mock product.
 *   2. `useDerivedProduct` unconditionally calls `useSelectedStore()`, which throws without a
 *      real `StoreLocatorProvider` ancestor.
 *   3. `item-attributes.tsx`'s `useCurrentBasket()` call has its own separate transitive chain
 *      (`useSFPayments` -> `useAppOrigin` -> `useOrigin`) that calls the SDK's
 *      `useServerContext()` and destructures `res` from it unconditionally, before `useOrigin`'s
 *      own `typeof window !== 'undefined'` branch (which never touches `res`) is reached. This
 *      file previously mocked `useCurrentBasket` away entirely, which hid this bug completely —
 *      unmocked now so this suite actually exercises the real chain. `ServerContext.Provider`
 *      with `value={{}}` matches exactly what the real app's own browser bootstrap supplies
 *      client-side (`ssr/browser/main.js`'s `OuterApp`) — confirmed by reading that file.
 *
 * Deliberately does NOT use index.test.tsx's harness — that file mocks the whole
 * `@salesforce/retail-react-app/app/hooks` barrel's `useDerivedProduct`, which would hide both
 * bugs this file exists to catch. This renders through the real, unmocked `useDerivedProduct` ->
 * `useVariationAttributes` -> `isVariantValueOrderable` / `useSelectedStore` chain, with a real
 * `StoreLocatorProvider` ancestor.
 *
 * `useMultiSite` and `useCurrency` are still mocked, for a reason that has nothing to do with
 * this build's own logic: `@salesforce/retail-react-app/app/contexts` (the barrel both
 * `MultiSiteProvider`/`CurrencyProvider` and `use-multi-site.js`/`use-currency.js` resolve
 * through) is a `.js` file containing inline JSX, which Vite's transform cannot parse as a
 * plain `.js` file — confirmed empirically (this file's first draft imported `MultiSiteProvider`
 * from that barrel directly and vitest failed at import-analysis on
 * `app/contexts/index.js:49`, not at any assertion). This is the same parse failure
 * item-variant/index.test.tsx's own docblock already documents and works around by mocking
 * `use-multi-site` instead of using a real `MultiSiteProvider`; extended here to `useCurrency`
 * for the same reason. `StoreLocatorProvider` itself is real: `use-selected-store.js` and
 * `store-locator-provider.jsx` both import `StoreLocatorContext` via that file's own direct path
 * (`.../app/contexts/store-locator-provider`), never through the barrel, so it never hits this
 * parse wall — confirmed by reading both files' imports, not assumed.
 *
 * Two more pragmatic mocks, both explained inline at their own `vi.mock`/`beforeEach`: `useStores`
 * (an unrelated dual-module-instance QueryClient issue, not this build's own code) and a
 * `window.matchMedia` polyfill (jsdom has none; item-price.tsx's `useBreakpointValue` needs it —
 * the same pre-existing gap and fix product-item/index.test.tsx's own `beforeEach` already uses).
 * Neither affects what this file actually proves: that a real `StoreLocatorProvider` ancestor and
 * an array-valued `variants` together stop the render from throwing.
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { CommerceApiProvider } from '@salesforce/commerce-sdk-react';
import { StoreLocatorProvider } from '@salesforce/retail-react-app/app/contexts/store-locator-provider';
import { ServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/contexts';
import theme from 'app/theme';
import ProductItem from '.';

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(() => ({ site: { id: 'ZimmermannAU' }, buildUrl: (path: string) => path })),
}));

// Cannot use this factory's `importOriginal` here: it resolves the barrel itself
// (`app/hooks/index.js`), which re-exports `useCurrency` from `use-currency.js`, which imports
// `CurrencyContext` from the broken `app/contexts` barrel — so `importOriginal()` transitively
// hits the same parse wall as importing `MultiSiteProvider` does (confirmed empirically: this
// was the first thing tried here, and it failed at the identical `app/contexts/index.js:49`
// parse error). `vi.importActual` on `use-derived-product`'s own direct sub-path sidesteps it —
// that file's own dependency chain never touches `app/contexts` (confirmed by grepping it and
// every hook it imports).
vi.mock('@salesforce/retail-react-app/app/hooks', async () => {
  const { useDerivedProduct } = await vi.importActual<
    typeof import('@salesforce/retail-react-app/app/hooks/use-derived-product')
  >('@salesforce/retail-react-app/app/hooks/use-derived-product');
  return {
    useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
    useDerivedProduct,
  };
});

// Same fix as product-item/index.test.tsx's own: PromoPopover imports the base SFCC icons
// barrel, which has a top-level side effect that throws under Vitest (testing.md's documented
// ZimmIcon gap, same root cause via a different import path).
vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
}));

// SFCC-795 rework (ZimmInlineMessage's warning icon): ProductItem -> ZimmInlineMessage ->
// ZimmIcon -> the base SFCC icons barrel is a new static import chain as of this rework, hitting
// the identical top-level-side-effect crash the mock above already works around for
// PromoPopover's own path to that same barrel. Neither test below passes a `message` prop, so the
// icon never needs to render distinguishably — testing.md's own documented canonical form
// (`ZimmIcon: () => null`) applies directly, no props need forwarding.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: () => null,
}));

// `useStores` is mocked too (in addition to usePromotions/useProducts/useProduct, needed for the
// same reason as product-item/index.test.tsx's own): the REAL `useSelectedStore` (unmocked, the
// actual thing this file proves doesn't throw) calls it internally, and the real `useStores` hit
// an unrelated environment issue here — `@tanstack/react-query`'s `useQueryClient()` not finding
// this file's own `QueryClientProvider` (a dual-module-instance style mismatch, not anything this
// build's own code controls). Mocking only `useStores` still exercises `useSelectedStore`'s own
// real body — including the `useContext(StoreLocatorContext)` throw-if-missing check this file
// exists to prove no longer throws — while sidestepping that unrelated plumbing issue.
vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
  return {
    ...actual,
    usePromotions: () => ({ data: undefined }),
    useProducts: () => ({ data: undefined, isLoading: false }),
    useProduct: () => ({ data: undefined, isLoading: false }),
    useStores: () => ({ data: undefined, isLoading: false }),
    // Same dual-module-instance QueryClient issue as useStores above, surfacing here now that
    // useCurrentBasket (unmocked, see this file's own docblock) calls this for real internally.
    useCustomerBaskets: () => ({ data: undefined, isLoading: false }),
  };
});

const storyQueryClient = new QueryClient({
  defaultOptions: { queries: { retry: false, refetchOnWindowFocus: false } },
});

// `useStores` (called for real inside the real `useSelectedStore`, unmocked above) is left real
// too — it resolves with `enabled: false` (no selectedStoreId in this jsdom's empty
// localStorage), so it registers a disabled query and never actually fetches, matching
// index.stories.tsx's own documented reasoning for its inert CommerceApiProvider/proxy setup.
const renderWithStoryProviders = (ui: React.ReactElement) =>
  render(
    <ServerContext.Provider value={{}}>
      <ChakraProvider theme={theme}>
        <MemoryRouter>
          <QueryClientProvider client={storyQueryClient}>
            <CommerceApiProvider
              clientId="00000000-0000-0000-0000-000000000000"
              organizationId="f_ecom_storybook_001"
              shortCode="storybook"
              siteId="ZimmermannAU"
              locale="en-AU"
              currency="AUD"
              proxy="https://storybook.invalid/mobify/proxy/api"
              redirectURI="https://storybook.invalid/callback"
              disableAuthInit
              silenceWarnings
            >
              <StoreLocatorProvider config={{ defaultCountryCode: 'AU', defaultPostalCode: '2000' }}>
                <IntlProvider locale="en-AU" defaultLocale="en-AU">
                  {ui}
                </IntlProvider>
              </StoreLocatorProvider>
            </CommerceApiProvider>
          </QueryClientProvider>
        </MemoryRouter>
      </ChakraProvider>
    </ServerContext.Provider>,
  );

// Mirrors index.stories.tsx's own MOCK_LINE_ITEM shape, including the round 2 `variants: []` fix.
const MOCK_LINE_ITEM = {
  itemId: 'a1b2c3d4e5f6a1b2c3d4e5f6',
  productId: '25595021M',
  id: '25595021M',
  productName: 'Lilac Sand Silk Midi Dress',
  name: 'Lilac Sand Silk Midi Dress',
  price: 495,
  priceAfterItemDiscount: 495,
  pricePerUnit: 495,
  quantity: 1,
  stepQuantity: 1,
  minOrderQuantity: 1,
  imageGroups: [
    {
      viewType: 'small',
      images: [{ alt: 'Lilac Sand Silk Midi Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
    },
  ],
  variationAttributes: [
    { id: 'color', name: 'Colour', values: [{ value: 'JJ5FUXX', name: 'Lilac Sand', orderable: true }] },
    { id: 'size', name: 'Size', values: [{ value: 'ONESIZE', name: 'One Size', orderable: true }] },
  ],
  variationValues: { color: 'JJ5FUXX', size: 'ONESIZE' },
  variants: [],
};

describe('ProductItem — Storybook story render (SFCC-270 round 2)', () => {
  // jsdom has no matchMedia implementation, and item-price.tsx's `isDesktop` uses
  // useBreakpointValue internally, which calls it — unrelated to either bug this file exists to
  // catch, same pre-existing gap and same per-file polyfill product-item/index.test.tsx's own
  // beforeEach already uses (not a change to the frozen vitest.setup.ts).
  beforeEach(() => {
    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: vi.fn().mockImplementation((query: string) => ({
        matches: false,
        media: query,
        onchange: null,
        addListener: vi.fn(),
        removeListener: vi.fn(),
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        dispatchEvent: vi.fn(),
      })),
    });
  });

  test('Default-equivalent: renders through the real, unmocked useDerivedProduct/useSelectedStore chain without throwing', () => {
    expect(() =>
      renderWithStoryProviders(
        <ProductItem product={MOCK_LINE_ITEM} primaryAction={<button type="button">Remove</button>} />,
      ),
    ).not.toThrow();

    expect(screen.getByRole('heading', { level: 2 })).toHaveTextContent('Lilac Sand Silk Midi Dress');
  });

  test('GiftCard-equivalent: hideStepperAndActions renders through the real chain without throwing, and hides the actions', () => {
    expect(() =>
      renderWithStoryProviders(
        <ProductItem
          product={MOCK_LINE_ITEM}
          primaryAction={<button type="button">Remove</button>}
          secondaryActions={<button type="button">Edit</button>}
          hideStepperAndActions
        />,
      ),
    ).not.toThrow();

    expect(screen.queryByRole('button', { name: 'Remove' })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: 'Edit' })).not.toBeInTheDocument();
  });
});

